package com.bank.stocktrade.service;

import java.util.logging.Logger;

// Greedy single-pass profit: running minimum vs summing positive gains.
public class StockTradingService {
    private static final Logger log = Logger.getLogger(StockTradingService.class.getName());

    public int maxSingleTrade(int[] prices) {
        if (prices.length == 0) return 0;
        int minSoFar = prices[0], best = 0;                // best buy price so far
        for (int p : prices) {
            minSoFar = Math.min(minSoFar, p);              // cheapest day to have bought
            best = Math.max(best, p - minSoFar);           // best profit selling today
        }
        final int result = best;
        log.info(() -> "Max profit, single trade = " + result);
        return best;
    }

    public int maxUnlimitedTrades(int[] prices) {
        int profit = 0;
        for (int i = 1; i < prices.length; i++) {
            if (prices[i] > prices[i - 1]) {               // capture every upward step
                profit += prices[i] - prices[i - 1];
            }
        }
        final int result = profit;
        log.info(() -> "Max profit, unlimited trades = " + result);
        return profit;
    }
}
