package com.bank.stocktrade;

import com.bank.stocktrade.service.StockTradingService;
import java.util.logging.Logger;

public class StockTradingApplication {
    private static final Logger log = Logger.getLogger(StockTradingApplication.class.getName());

    public static void main(String[] args) {
        StockTradingService service = new StockTradingService();
        int[] prices = {7, 1, 5, 3, 6, 4};                 // daily closing prices (scaled)
        int single = service.maxSingleTrade(prices);
        int unlimited = service.maxUnlimitedTrades(prices);
        log.info(() -> "Single=" + single + ", Unlimited=" + unlimited);
    }
}
